//! The generated flash-attention tuning table.
//!
//! # Provenance
//!
//! Mirrors `fa_vec_tuned_table` and the three structs around it, in the
//! reference checkout:
//!
//! - `llama.cpp/ggml/src/ggml-metal/ggml-metal-tuning.cpp` — the table
//! - `llama.cpp/ggml/src/ggml-metal/ggml-metal-tuning.h`   — the structs
//!
//! all at v0.7.0 (`620d2225c`).
//!
//! # Generated, not written
//!
//! The C's own comment on the table reads "Generated by
//! `ggml-metal-tuning fa-vec`; do not hand-edit." `scripts/gen-tuning-table`
//! writes the rows and the count below from the C: 936 rows at v0.3.0,
//! 3,565 at v0.4.0, 3,884 at v0.4.1, 1,033 at v0.5.0 and v0.6.0 -- past the point where
//! copying by hand is honest work. It matches **every** row and skips none, checks its
//! count against an independent one, and reproduced the hand-checked v0.3.0
//! table byte for byte. `make tuning-diff` then compares the lookup against
//! the reference's over the whole key space, which is what actually proves
//! the transcription. Do not edit the generated parts; rerun the script.
//!
//! # Keyed by GPU family since v0.5.0
//!
//! Until v0.4.1 a row's first field was a per-SKU `ggml_metal_device_id`,
//! with a family fallback to one representative SKU. v0.5.0 re-keys the
//! table by Apple GPU family -- the `N` of `MTLGPUFamilyAppleN`, 7 to 10 --
//! pooling each family's SKUs into one row set, and drops the fallback. The
//! SKU enum is no longer the table's business; it lives in `device_c.zig`,
//! which `scripts/gen-tuning-table` still writes from `ggml-metal-device.h`.

const std = @import("std");
const impl = @import("../impl.zig");

const c = impl.c;

/// Mirrors `fa_vec_key_t` (ggml-metal-tuning.h:33 @620d2225c).
///
/// Eight bytes with no padding, which the C's `static_assert` exists to
/// guarantee because `find_cfg` compares keys with `memcmp`.
pub const Key = extern struct {
    /// The Apple GPU family, `N` in `MTLGPUFamilyAppleN`.
    family: i8,
    dtype: i8,
    dk: i16,
    dv: i16,
    ne11_b: i8,
    ne01_b: i8,
};

/// Mirrors `struct fa_vec_cfg_t` (ggml-metal-tuning.h:44 @620d2225c).
pub const Cfg = extern struct {
    Q: i8,
    NE: i8,
};

/// Mirrors `struct fa_vec_entry_t` (ggml-metal-tuning.h:49 @620d2225c).
pub const Entry = extern struct {
    key: Key,
    cfg: Cfg,
};

