comptime {
    // The C's `static_assert(sizeof(fa_vec_key_t) == 8, …)`, which
    // licenses the `memcmp` the lookup ports as one `u64` compare.
    std.debug.assert(@sizeOf(Key) == 8);
    std.debug.assert(@sizeOf(Cfg) == 2);
    std.debug.assert(@sizeOf(Entry) == 10);
    // The row count the extraction was checked against.
    std.debug.assert(fa_vec_tuned_table.len == 1033);
}

// -----------------------------------------------------------------------------
// Unit Tests

test {
    std.testing.refAllDecls(@This());
}

test "no key appears twice" {
    // Not relied on by the lookup -- `find_cfg` is a linear scan and the
    // first match wins -- but upstream's table has no duplicate, so one
    // here would mean the extraction doubled a row. The rows are not in
    // key order (v0.5.0 lists some domain defaults between exact rows), so
    // every pair is compared, not neighbours.
    for (fa_vec_tuned_table, 0..) |a, i| {
        const ka: u64 = @bitCast(std.mem.toBytes(a.key));
        for (fa_vec_tuned_table[i + 1 ..]) |b| {
            try std.testing.expect(ka != @as(u64, @bitCast(std.mem.toBytes(b.key))));
        }
    }
}
